import numpy as np

def kernel_multicuadrico(r, epsilon=1.0):
    return np.sqrt(1.0 + (epsilon * r) ** 2)

def ajustar_rbf(nodos, valores, epsilon=1.0):
    # Matriz de distancias euclidianas entre todos los pares de nodos
    diff = nodos[:, np.newaxis, :] - nodos[np.newaxis, :, :]
    distancias = np.linalg.norm(diff, axis=-1)
    Phi = kernel_multicuadrico(distancias, epsilon)
    pesos = np.linalg.solve(Phi, valores)
    return pesos
